import { Component } from '@angular/core';

interface SkillGroup {
  category: string;
  icon: string;
  color: string;
  skills: string[];
}

@Component({
  selector: 'app-skills',
  templateUrl: './skills.component.html',
  styleUrls: ['./skills.component.css']
})
export class SkillsComponent {
  activeCategory = 'all';

  skillGroups: SkillGroup[] = [
    {
      category: 'Backend',
      icon: 'fas fa-server',
      color: '#00d4ff',
      skills: ['Java 8', 'Java 17', 'Spring Boot 2.x/3.x', 'Spring Framework', 'Spring Security', 'Spring Data JPA', 'Hibernate ORM', 'REST API', 'Microservices']
    },
    {
      category: 'Frontend',
      icon: 'fas fa-desktop',
      color: '#7c3aed',
      skills: ['Angular 12+', 'TypeScript', 'JavaScript', 'HTML5', 'CSS3', 'Bootstrap', 'ExtJS']
    },
    {
      category: 'Database',
      icon: 'fas fa-database',
      color: '#10b981',
      skills: ['PostgreSQL', 'MySQL', 'Database Design', 'Query Optimization', 'Reverse Engineering', 'SQL']
    },
    {
      category: 'DevOps & Tools',
      icon: 'fas fa-tools',
      color: '#f59e0b',
      skills: ['Maven', 'Git', 'GitHub', 'GitLab', 'Docker (Basic)', 'Apache Tomcat', 'CI/CD Pipelines', 'IntelliJ IDEA', 'VS Code']
    },
    {
      category: 'Cloud',
      icon: 'fas fa-cloud',
      color: '#ef4444',
      skills: ['AWS S3', 'GCP Cloud Storage', 'GCP IAM', 'OAuth 2.0', 'Cloud Functions']
    },
    {
      category: 'Quality',
      icon: 'fas fa-shield-alt',
      color: '#06b6d4',
      skills: ['JUnit', 'SonarQube', 'PMD', 'SpotBugs', 'Checkstyle', 'TDD', 'Code Review', 'Integration Testing']
    }
  ];

  hexToRgb(hex: string): string {
    const r = parseInt(hex.slice(1, 3), 16);
    const g = parseInt(hex.slice(3, 5), 16);
    const b = parseInt(hex.slice(5, 7), 16);
    return `${r}, ${g}, ${b}`;
  }

  proficiencies = [
    { name: 'Java / Spring Boot', level: 90 },
    { name: 'Microservices', level: 85 },
    { name: 'Angular / TypeScript', level: 80 },
    { name: 'REST API Design', level: 88 },
    { name: 'PostgreSQL / MySQL', level: 80 },
    { name: 'Code Quality Tools', level: 85 }
  ];
}
<section id="skills" class="section skills-section">
  <div class="container">
    <div class="section-header">
      <p class="section-label">What I Know</p>
      <h2 class="section-title">Technical <span>Skills</span></h2>
      <div class="section-divider"></div>
      <p class="section-sub">A broad toolkit honed across enterprise projects, government portals, and cloud-native systems.</p>
    </div>

    <!-- Skill groups -->
    <div class="skills-grid">
      <div class="skill-group card" *ngFor="let group of skillGroups">
        <div class="group-header">
          <div class="group-icon" [style.background]="'rgba(' + hexToRgb(group.color) + ', 0.1)'"
               [style.border-color]="'rgba(' + hexToRgb(group.color) + ', 0.25)'">
            <i [class]="group.icon" [style.color]="group.color"></i>
          </div>
          <h3 class="group-title">{{group.category}}</h3>
        </div>
        <div class="skill-tags">
          <span class="skill-tag" *ngFor="let skill of group.skills">{{skill}}</span>
        </div>
      </div>
    </div>

    <!-- Proficiency bars -->
    <div class="proficiency-section">
      <h3 class="proficiency-title">Core Proficiencies</h3>
      <div class="proficiency-bars">
        <div class="bar-item" *ngFor="let p of proficiencies">
          <div class="bar-info">
            <span class="bar-name">{{p.name}}</span>
            <span class="bar-percent">{{p.level}}%</span>
          </div>
          <div class="bar-track">
            <div class="bar-fill" [style.width]="p.level + '%'"></div>
          </div>
        </div>
      </div>
    </div>

  </div>
</section>
